// ============================================================
// Drill Script — the authoring vocabulary for SuperCoach drill
// animations. See docs/animation-system.md for the full guide.
//
// A scene describes WHAT HAPPENS in football terms (run, dribble,
// pass, shoot, tackle, save…), never where the ball is. The
// compiler (compile.js) derives every ball position from who has
// it or which kick it is in, so the ball can never move without a
// foot (or hand, or rebounder) touching it.
//
// Everything here returns plain JSON, so scenes can be stored,
// diffed, or generated by the AI layer without code.
// ============================================================

// ---- Scene ----------------------------------------------------
// scene({
//   area:  '20 x 20 square',               // label in the control bar
//   field: { cones, gates, goals, zones, … },// static kit, see props.jsx
//   cast:  { p1: player('a', '1', 20, 30), … },
//   balls: { b: 'p1' }  or  { b: [50, 32] }, // holder id, or loose at x,y
//   beats: [ beat('Caption', 1.2, run(…), pass(…)), … ],
//   trails: true | 'ball' | false,           // pressed grass: all / ball only / none
// })
export const scene = (s) => s

// A beat is one step of the story: an optional caption, a duration
// in seconds (omit to size it from the ball actions inside), and the
// actions that start together at the beginning of the beat.
//   beat('Pass into the gap', 1.2, pass('p1', 'p2'), run('p3', [60, 30]))
//   beat(1.0, run(...))          // no caption change
//   beat('One-touch round', pass(...), pass(...), pass(...))  // auto length
export function beat(...args) {
  let say, dur
  if (typeof args[0] === 'string') say = args.shift()
  if (typeof args[0] === 'number') dur = args.shift()
  return { say, dur, do: args.flat().filter(Boolean) }
}

// ---- Cast -----------------------------------------------------
// Teams: 'a' coral, 'b' blue, 'n' amber (coach / neutral),
// 'k' purple goalkeeper, 'x' grey (mannequin / passive defender).
export const player = (team, label, x, y, opts = {}) => ({ team, label, at: [x, y], ...opts })
export const keeper = (x, y, opts = {}) => ({ team: 'k', label: 'GK', at: [x, y], ...opts })
export const coach = (x, y, opts = {}) => ({ team: 'n', label: 'C', at: [x, y], ...opts })
// Illustrated kid for stretches (src/anim/kid.js). `pose` names: kid.js POSES.
export const figure = (team, x, y, opts = {}) => ({ team, at: [x, y], figure: true, pose: 'stand', ...opts })

// ---- Targets --------------------------------------------------
// Anywhere an action takes a destination you can pass:
//   [x, y]               a point on the pitch
//   [[x, y], [x, y]]     a route through waypoints (runs/dribbles)
//   'p2'                 a cast member (pass: their feet on arrival;
//                        run: where they are when you arrive)
//   rel(dx, dy)          relative to where the mover currently is
//   'goal:0'             goal 0's mouth (shots); add {aim} to place it
//   'rebounder:0'        rebounder face
//   'ball:t1'            another (resting) ball — pass/shoot knocks it
//                        away (opts.knock = where it flies, e.g. off a cone)
export const rel = (dx, dy) => ({ rel: [dx, dy] })

// ---- Player movement -----------------------------------------
// Without a beat duration a run uses natural pace for its length.
//   pace: 'walk' | 'jog' | 'run' | 'sprint'
//   delay: seconds after the beat starts
//   dur:   seconds to arrive (default: fill the beat)
//   hop:   peak height of a single jump over the run (hurdles, headers)
//   bounce: number of little hops along the run (ladders, kangaroo hops)
//   dive: true — keeper dive stretch
export const run = (who, to, opts = {}) => ({ do: 'run', who, to, ...opts })
// Same as run, but the player keeps the ball at their feet with
// visible little touches. Fails validation if they don't have it.
export const dribble = (who, to, opts = {}) => ({ do: 'dribble', who, to, ...opts })
// Turn to look at a point or player without moving.
export const face = (who, target, opts = {}) => ({ do: 'face', who, target, ...opts })

// ---- Ball actions ---------------------------------------------
// Ball actions chain: inside a beat (and across beats) a ball action
// waits until the ball has actually arrived with the kicker, so
//   beat('One-touch triangle', pass('a','b'), pass('b','c'), pass('c','a'))
// plays as three consecutive first-time passes.
//
// Common opts:
//   dur    flight time (default from distance + kind of kick)
//   arc    peak height of a lofted ball (chip, cross, throw)
//   curve  sideways bend at mid-flight (+ = bends to the kicker's right)
//   at     receiving height: 'feet' | 'knee' | 'chest' | 'head' | 'hands'
//   hit    [x, y] — ball strikes the receiver and ricochets here (ball tag)
//   delay  seconds after the beat starts before the strike
// To play it into space, pass to a point and `collect` it.
export const pass = (from, to, opts = {}) => ({ do: 'pass', from, to, ...opts })
export const chip = (from, to, opts = {}) => ({ do: 'pass', from, to, arc: 6, ...opts })
export const cross = (from, to, opts = {}) => ({ do: 'pass', from, to, arc: 7, ...opts })
// Hands: throw/roll from a keeper or coach. Lands at the receiver's
// feet unless `at` says otherwise (a keeper catches at 'hands').
export const toss = (from, to, opts = {}) => ({ do: 'pass', from, to, arc: 5, hands: true, ...opts })
// shoot('p1', 'goal:0', { aim: -4, save: 'gk' })
//   aim   offset along the goal mouth (− = top/left post, + = other)
//   save  keeper id: keeper dives/steps and catches it
//   parry [x, y]: keeper palms it here instead of holding it
//   miss  true: goes wide past the post
//   bar   true (or [x, y] rebound spot): hits the crossbar and bounces out
export const shoot = (from, target, opts = {}) => ({ do: 'shoot', from, target, ...opts })
// A ball that is resting or arriving somewhere with no player
// (rebounder, wall, coach's hand) sent on to a target.
export const rebound = (to, opts = {}) => ({ do: 'rebound', to, ...opts })
// Run onto a loose ball and take control of it.
export const collect = (who, opts = {}) => ({ do: 'collect', who, ...opts })
// Defender closes in and wins the ball (`win: true`, default) or
// pokes it away to a point (`to: [x, y]`).
export const tackle = (who, victim, opts = {}) => ({ do: 'tackle', who, victim, win: !opts.to, ...opts })
// Touch-tag (no ball): chaser runs in and tags the victim.
export const tag = (who, victim, opts = {}) => ({ do: 'tag', who, victim, ...opts })
// Keepy-ups at the player's feet.
export const juggle = (who, opts = {}) => ({ do: 'juggle', who, count: 4, ...opts })
// Put the ball down / pick it up for hands-based drills.
export const pickUp = (who, opts = {}) => ({ do: 'pickup', who, ...opts })
export const drop = (who, opts = {}) => ({ do: 'drop', who, ...opts })
// Step away and leave the ball resting where it is.
export const leave = (who, opts = {}) => ({ do: 'leave', who, ...opts })

// ---- Communication --------------------------------------------
// Speech bubble over a cast member ("Red light!", "Man on!").
export const shout = (who, text, opts = {}) => ({ do: 'shout', who, text, ...opts })
// Stretch figures morph into a named pose.
export const pose = (who, name, opts = {}) => ({ do: 'pose', who, name, ...opts })
// Pulse a ring on a spot or player to draw the eye ("this is the gate").
//   r: radius, rate: pulse speed (slow ~1.6 = breathing), color
export const highlight = (target, opts = {}) => ({ do: 'highlight', target, ...opts })
